// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const D = new Float64Array( 5 );

	dlasrt.ndarray( 'I', 3, D, 1, 0, '5', 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, true, 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, false, 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, null, 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, undefined, 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, [], 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, {}, 1, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a seventh argument which is not a number...
{
	const D = new Float64Array( 5 );
	const stack = new Float64Array( 64 );

	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, '5', 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, true, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, false, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, null, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, undefined, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, [], 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, {}, 0 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a eighth argument which is not a number...
{
	const D = new Float64Array( 5 );
	const stack = new Float64Array( 64 );

	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, '5' ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, true ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, false ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, null ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, undefined ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, [] ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, {} ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const D = new Float64Array( 5 );
	const stack = new Float64Array( 64 );

	dlasrt.ndarray(); // $ExpectError
	dlasrt.ndarray( 'I' ); // $ExpectError
	dlasrt.ndarray( 'I', 3 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1 ); // $ExpectError
	dlasrt.ndarray( 'I', 3, D, 1, 0, stack, 1, 0, 10 ); // $ExpectError
}
